// Execution module â€?t signal fills at t+1 open; pessimistic cost default
// ---------------------------------------------------------------------------

/** Pessimistic default cost model (ç­–ç•¥ä½œè€…ä¸å®šä¹‰æˆæœ¬å‡è®¾â€”â€”é»˜è®¤æ‚²è§‚æ¡£, è·¨åŸŸå…¬å…±çºªå¾‹). */
export const DEFAULT_COSTS = Object.freeze({
	takerFeeBps: 10, // 10bp taker fee (Â§1.2.3)
