export const ENGINE_VERIFIER_ID = "k3-backtest-engine@1";
export const ANNUALIZATION_DAYS = 365; // âˆ?65 (crypto has no weekends), Â§1.2.3

function mean(xs: readonly number[]): number {
	return xs.length === 0 ? 0 : xs.reduce((a, b) => a + b, 0) / xs.length;
}

function std(xs: readonly number[]): number {
	if (xs.length < 2) return 0;
	const m = mean(xs);
	return Math.sqrt(xs.reduce((a, b) => a + (b - m) ** 2, 0) / (xs.length - 1));
}

export function sharpeAnnualized(dailyReturns: readonly number[]): number {
	const s = std(dailyReturns);
	if (s === 0) return 0;
	return (mean(dailyReturns) / s) * Math.sqrt(ANNUALIZATION_DAYS);
}

export function sortinoAnnualized(dailyReturns: readonly number[]): number {
	const downside = dailyReturns.filter((r) => r < 0);
	if (downside.length < 2) return 0;
	const dd = Math.sqrt(downside.reduce((a, b) => a + b ** 2, 0) / downside.length);
	if (dd === 0) return 0;
	return (mean(dailyReturns) / dd) * Math.sqrt(ANNUALIZATION_DAYS);
}

export function maxDrawdown(equity: readonly number[]): number {
	let peak = Number.NEGATIVE_INFINITY;
	let mdd = 0;
	for (const e of equity) {
		if (e > peak) peak = e;
		const dd = peak > 0 ? (peak - e) / peak : 0;
		if (dd > mdd) mdd = dd;
	}
	return mdd;
}

