/**
 * Runs the FIFO loop. DETERMINISTIC CONTRACT: no randomness, no hidden state, no clock reads â€”
 * same CSV + same params â‡?identical PerformanceReport (the verifier recomputes and compares
 * field by field; a report that cannot be recomputed is a stub and FAIL-KILLs, Â§5.2 å¤±è´¥è·¯å¾„â‘?.
 */
export function runBacktest(csv: string, config: EngineConfig, options: RunOptions = {}): PerformanceReport {
	if ((config.fillTiming ?? FILL_TIMING) !== FILL_TIMING) {
		throw new LookaheadError(
			`fillTiming "${config.fillTiming}" refused: signal at t must fill at t+1 open â€?a same-bar fill is ` +
				"lookahead in disguise (engine timing check, Â§5.2 designed failure path â‘?",
		);
	}
	const bars = parseOhlcvCsv(csv);
	if (bars.length < 3) throw new BacktestError("need â‰? bars for a signalâ†’fillâ†’mark cycle");
	const costs = config.costs ?? DEFAULT_COSTS;
	if (costs.takerFeeBps < 0 || costs.slippageBps < 0) throw new BacktestError("costs must be non-negative");
	const dataHash = snapshotHash(csv);
	const initialEquity = config.initialEquity ?? 10_000;

	config.strategy.init?.();

	// FIFO queue: market events are enqueued one bar at a time; orders emitted at t are only
	// serviceable when the t+1 MARKET event exists. The future is created by the loop, not read.
	const eventCounts: Record<string, number> = { MARKET: 0, SIGNAL: 0, ORDER: 0, FILL: 0 };
	let position = 0; // current position in [-1, 1] (fraction of equity in the asset)
	let pendingOrder: { target: number } | null = null;
	let equity = initialEquity;
	const equityCurve: number[] = [];
	const dailyReturns: number[] = [];
	let trades = 0;

	for (let t = 0; t < bars.length; t++) {
		eventCounts.MARKET += 1;
		const prevEquity = equity;

		// 1 Â· service the order queued at t-1: fill at THIS bar's open (t signal â†?t+1 open fill)
		if (pendingOrder !== null) {
			const target = pendingOrder.target;
			pendingOrder = null;
			const delta = target - position;
			if (delta !== 0) {
				const fillOpen = bars[t].open;
				const feeCost = Math.abs(delta) * equity * (costs.takerFeeBps / 10_000);
				const slipCost = Math.abs(delta) * equity * (costs.slippageBps / 10_000);
				equity -= feeCost + slipCost;
				position = target;
				trades += 1;
				eventCounts.FILL += 1;
				void fillOpen; // fill price is the open; PnL marks below use close-to-close on position
			}
		}

		// 2 Â· mark to market over this bar (position held during bar t earns close[t-1]â†’close[t])
		if (t > 0 && position !== 0) {
			const r = bars[t].close / bars[t - 1].close - 1;
			equity *= 1 + position * r;
		}

		// 3 Â· strategy sees ONLY bars[0..t] â€?a defensive slice; the future is absent, not hidden
		const view = makeView(bars.slice(0, t + 1));
		const rawTarget = config.strategy.next(view);
		if (!Number.isFinite(rawTarget)) throw new BacktestError(`strategy returned non-finite target at bar ${t}`);
		const target = Math.max(-1, Math.min(1, rawTarget));
		eventCounts.SIGNAL += 1;

		// 4 Â· queue the order for the NEXT bar (FIFO: it physically cannot fill before t+1)
		if (target !== position && t < bars.length - 1) {
			pendingOrder = { target };
			eventCounts.ORDER += 1;
		}

		equityCurve.push(equity);
		if (t > 0) dailyReturns.push(prevEquity > 0 ? equity / prevEquity - 1 : 0);
	}

	const report: PerformanceReport = Object.freeze({
		strategy: config.strategy.name,
		params: Object.freeze({ ...config.strategy.params }),
		data_hash: dataHash,
		bars: bars.length,
		trades,
		final_equity: equity,
		total_return: equity / initialEquity - 1,
		sharpe_annual: sharpeAnnualized(dailyReturns),
		sortino_annual: sortinoAnnualized(dailyReturns),
		max_drawdown: maxDrawdown(equityCurve),
		daily_returns: Object.freeze(dailyReturns),
		equity_curve: Object.freeze(equityCurve),
		costs: Object.freeze({ ...costs }),
		fill_timing: FILL_TIMING,
		event_counts: Object.freeze({ ...eventCounts }),
		minted_by: ENGINE_VERIFIER_ID,
		ledger_seq: null,
	});

	if (options.ledger) {
		const row = options.ledger.append({
			event_type: "quant.backtest_run",
			actor: { role: "gatekeeper" },
			action: "run_backtest",
			phase: options.phase ?? "quant",
			payload: {
				strategy: report.strategy,
				params: report.params as Record<string, number>,
				data_hash: report.data_hash,
				sharpe_annual: report.sharpe_annual,
				trades: report.trades,
				final_equity: report.final_equity,
			},
			idem_key: null,
		});
		return Object.freeze({ ...report, ledger_seq: row.seq });
	}
	return report;
}

// ---------------------------------------------------------------------------
// Verifier-side recomputation â€?the anti-stub gate (Â§6.2 RCON equivalent â‘?
// ---------------------------------------------------------------------------

/** Fields compared exactly; a report the engine cannot reproduce is a stub. */
export const RECOMPUTE_FIELDS: readonly (keyof PerformanceReport)[] = Object.freeze([
	"bars",
	"trades",
	"final_equity",
	"total_return",
	"sharpe_annual",
	"sortino_annual",
	"max_drawdown",
]);

export interface RecomputeVerdict {
	readonly valid: boolean;
	readonly mismatches: readonly string[];
}

/**
 * Independent recomputation: the verifier re-runs the engine from the same CSV + params and
 * compares field by field. Performance JSON emitted WITHOUT an engine run (spawn-resources shape,
 * Factorio) cannot survive this â€?the agent's numbers have no standing; only the engine's do.
 */
export function recomputeAndCompare(csv: string, config: EngineConfig, claimed: PerformanceReport): RecomputeVerdict {
	const fresh = runBacktest(csv, config);
	const mismatches: string[] = [];
	if (claimed.data_hash !== fresh.data_hash) mismatches.push(`data_hash: ${claimed.data_hash} â‰?${fresh.data_hash}`);
	for (const f of RECOMPUTE_FIELDS) {
		const a = claimed[f] as number;
		const b = fresh[f] as number;
		const equal = typeof a === "number" && typeof b === "number" ? Math.abs(a - b) < 1e-12 : a === b;
		if (!equal) mismatches.push(`${f}: claimed ${a} â‰?recomputed ${b}`);
	}
	return { valid: mismatches.length === 0, mismatches: Object.freeze(mismatches) };
}

/**
 * Report standing = ledger row existence (same discipline as W7's chain provenance): a report
 * whose ledger_seq does not point at a verifier-minted `quant.backtest_run` row is refused even
 * if its numbers happen to be right â€?provenance is the LEDGER, not the minted_by string.
 */
export function verifyRunProvenance(
	report: PerformanceReport,
	rows: readonly {
		seq: number;
		event_type: string;
		actor: { role: string };
		payload: Record<string, unknown> | null;
	}[],
): { valid: boolean; reason: string } {
	if (report.minted_by !== ENGINE_VERIFIER_ID) {
		return { valid: false, reason: `minted_by "${report.minted_by}" is not the engine` };
	}
	if (report.ledger_seq === null) return { valid: false, reason: "report carries no ledger_seq (never minted)" };
	const row = rows.find((r) => r.seq === report.ledger_seq);
	if (!row) return { valid: false, reason: `no ledger row at seq ${report.ledger_seq}` };
	if (row.event_type !== "quant.backtest_run" || row.actor.role !== "gatekeeper") {
		return { valid: false, reason: `seq ${report.ledger_seq} is not a verifier-minted quant.backtest_run row` };
	}
	if ((row.payload?.data_hash as string) !== report.data_hash) {
		return { valid: false, reason: "ledger row data_hash does not match the report" };
	}
	return { valid: true, reason: "verifier-minted" };
}

// ---------------------------------------------------------------------------
// Built-in reference strategies (used by golden cases; pure functions of the view)
// ---------------------------------------------------------------------------

/** SMA dual moving-average crossover (Q1's strategy family). */
export function smaCrossStrategy(fast: number, slow: number): Strategy {
	if (fast >= slow || fast < 1) throw new BacktestError(`sma params invalid: fast ${fast} must be < slow ${slow}`);
	return {
		name: "sma_cross",
		params: Object.freeze({ fast, slow }),
		next(view: MarketView): number {
			if (view.length < slow) return 0;
			const closes = view.closes(slow);
			const fastMa = mean(closes.slice(closes.length - fast));
			const slowMa = mean(closes);
			return fastMa > slowMa ? 1 : 0;
		},
	};
}

/** Z-score mean reversion (strong-verifier submode exemplar). */
export function meanReversionStrategy(lookback: number, entryZ: number): Strategy {
	return {
		name: "mean_reversion_z",
		params: Object.freeze({ lookback, entryZ }),
		next(view: MarketView): number {
			if (view.length < lookback) return 0;
			const closes = view.closes(lookback);
			const m = mean(closes);
			const s = std(closes);
			if (s === 0) return 0;
			const z = (view.last.close - m) / s;
			if (z < -entryZ) return 1;
			if (z > entryZ) return -1;
			return 0;
		},
	};
}

/** Time-series momentum (strong-medium submode exemplar). */
export function momentumStrategy(lookback: number): Strategy {
	return {
		name: "ts_momentum",
		params: Object.freeze({ lookback }),
		next(view: MarketView): number {
			if (view.length < lookback + 1) return 0;
			const closes = view.closes(lookback + 1);
			return closes[closes.length - 1] > closes[0] ? 1 : 0;
		},
	};
}
