 * K3 implant Â· W8-T8 Â· quant domain Â· reference backtest engine (event-driven, minimal viable).
 *
 * COMPONENT TRIPLE (three_domains.md Â§1.2.3, Â§6.2 quant; three_domain_design_inputs.md Â§2.1)
 * - Reason to exist : the quant domain's hard verifier is "backtest numbers recomputable by a
 *                     deterministic engine". That engine must make lookahead PHYSICALLY
 *                     impossible (an environment property, not an instrument property): the
 *                     strategy runs inside a FIFO event loop where future events have not been
 *                     generated yet, and the market view handed to the strategy structurally
 *                     contains only past bars. A vectorized backtest can only ever GUARD against
 *                     lookahead (instrument); this engine removes the future from the strategy's
 *                     world (environment).
 * - Axiom binding   : Axiom 9 (push architected: timing rules are engine structure, not prompt
 *                     text), Axiom 5 (every run minted as a ledger row; report standing = ledger
 *                     row existence).
 * - Deprecation     : cost defaults may be re-graded after calibration; the FIFO/next-bar-fill
 *                     structure and the deterministic CSV-in/JSON-out contract are not
 *                     deprecable. Vectorized scans are allowed ONLY for coarse parameter
 *                     screening and their output has NO adjudication standing (Â§1.2.3).
 *
 * FIVE MODULES (Â§1.2.3): DataHandler (one-way time cursor over OHLCV) â†?Strategy (init/next) â†’
 * Portfolio (signal â†?target position) â†?Execution (signal at t fills at t+1 open, taker fee
 * 10bp + slippage, pessimistic default) â†?Performance (equity curve, âˆ?65-annualized Sharpe,
 * Sortino, MaxDD, trade count) + Risk analysis.
 */

import { createHash } from "node:crypto";
import type { EventLedger } from "../../ledger/event-ledger.js";

export class BacktestError extends Error {
	constructor(message: string) {
		super(message);
		this.name = "BacktestError";
	}
}

/** Thrown when code inside the loop asks for data at an index beyond the cursor. */
export class LookaheadError extends Error {
	constructor(message: string) {
		super(message);
		this.name = "LookaheadError";
	}
}

// ---------------------------------------------------------------------------
// Data module â€?point-in-time OHLCV, one-way cursor, content-hashed snapshot
// ---------------------------------------------------------------------------

export interface Bar {
	readonly ts: number; // epoch ms, strictly increasing
	readonly open: number;
	readonly high: number;
	readonly low: number;
	readonly close: number;
	readonly volume: number;
}

/** CSV in (ts,open,high,low,close,volume header required) â€?deterministic parse, no locale. */
export function parseOhlcvCsv(csv: string): readonly Bar[] {
	const lines = csv.trim().split(/\r?\n/);
	if (lines.length < 2) throw new BacktestError("CSV must carry a header and at least one bar");
	const header = lines[0].trim().toLowerCase();
	if (header !== "ts,open,high,low,close,volume") {
		throw new BacktestError(`CSV header must be exactly "ts,open,high,low,close,volume", got "${header}"`);
	}
	const bars: Bar[] = [];
	let prevTs = Number.NEGATIVE_INFINITY;
	for (let i = 1; i < lines.length; i++) {
		const parts = lines[i].split(",");
		if (parts.length !== 6) throw new BacktestError(`line ${i + 1}: expected 6 fields, got ${parts.length}`);
		const [ts, open, high, low, close, volume] = parts.map(Number);
		if (![ts, open, high, low, close, volume].every(Number.isFinite)) {
			throw new BacktestError(`line ${i + 1}: non-finite field`);
		}
		if (ts <= prevTs) {
			throw new BacktestError(`line ${i + 1}: timestamps must be strictly increasing (point-in-time contract)`);
		}
		if (low > high || open <= 0 || close <= 0) throw new BacktestError(`line ${i + 1}: malformed OHLC`);
		prevTs = ts;
		bars.push(Object.freeze({ ts, open, high, low, close, volume }));
	}
	return Object.freeze(bars);
}

/** Snapshot hash â€?data snapshots are registered by content hash before any run (Â§1.2.3 æ•°æ®å±?. */
export function snapshotHash(csv: string): string {
	return createHash("sha256").update(csv).digest("hex");
}

/**
 * The market view handed to the strategy at cursor position t. ENVIRONMENT-NATURE CONSTRUCTION:
 * the view's backing array is a slice ending at t â€?bars after t are structurally ABSENT from
 * the object, not merely guarded behind an index check. Even full reflection over the view
 * cannot recover a future bar, because the FIFO loop has not delivered it yet (Â§6.2: æ—¶é—´ç®­å¤´ç”±
 * å¼•æ“Žç»“æž„å®žçŽ°).
 */
export interface MarketView {
	/** Number of bars visible (cursor position + 1). */
	readonly length: number;
	/** Bar at absolute index i (0-based); i must be â‰?cursor. */
	bar(i: number): Bar;
	/** Closes of the last n visible bars (for indicator windows). */
	closes(n: number): readonly number[];
	readonly last: Bar;
}

function makeView(past: readonly Bar[]): MarketView {
	// `past` is already a defensive copy sliced at the cursor â€?the future is not in scope here.
	return Object.freeze({
		length: past.length,
		bar(i: number): Bar {
			if (i < 0 || i >= past.length) {
				throw new LookaheadError(
					`bar(${i}) outside the visible window [0, ${past.length - 1}]: future events have not been generated yet`,
				);
			}
			return past[i];
		},
		closes(n: number): readonly number[] {
			const k = Math.min(n, past.length);
			return past.slice(past.length - k).map((b) => b.close);
		},
		last: past[past.length - 1],
	});
}

// ---------------------------------------------------------------------------
// Strategy module â€?init/next interface; emits target positions in [-1, 1]
// ---------------------------------------------------------------------------

export interface Strategy {
	readonly name: string;
	readonly params: Readonly<Record<string, number>>;
	init?(): void;
