 */
export function runBacktest(csv: string, config: EngineConfig, options: RunOptions = {}): PerformanceReport {
	if ((config.fillTiming ?? FILL_TIMING) !== FILL_TIMING) {
		throw new LookaheadError(
			`fillTiming "${config.fillTiming}" refused: signal at t must fill at t+1 open â€?a same-bar fill is ` +
