	if (bars.length < 3) throw new BacktestError("need â‰? bars for a signalâ†’fillâ†’mark cycle");
	const costs = config.costs ?? DEFAULT_COSTS;
	if (costs.takerFeeBps < 0 || costs.slippageBps < 0) throw new BacktestError("costs must be non-negative");
	const dataHash = snapshotHash(csv);
	const initialEquity = config.initialEquity ?? 10_000;

	config.strategy.init?.();

	// FIFO queue: market events are enqueued one bar at a time; orders emitted at t are only
	// serviceable when the t+1 MARKET event exists. The future is created by the loop, not read.
	const eventCounts: Record<string, number> = { MARKET: 0, SIGNAL: 0, ORDER: 0, FILL: 0 };
	let position = 0; // current position in [-1, 1] (fraction of equity in the asset)
	let pendingOrder: { target: number } | null = null;
	let equity = initialEquity;
	const equityCurve: number[] = [];
	const dailyReturns: number[] = [];
	let trades = 0;

	for (let t = 0; t < bars.length; t++) {
		eventCounts.MARKET += 1;
		const prevEquity = equity;

		// 1 Â· service the order queued at t-1: fill at THIS bar's open (t signal â†?t+1 open fill)
		if (pendingOrder !== null) {
			const target = pendingOrder.target;
			pendingOrder = null;
			const delta = target - position;
			if (delta !== 0) {
				const fillOpen = bars[t].open;
				const feeCost = Math.abs(delta) * equity * (costs.takerFeeBps / 10_000);
				const slipCost = Math.abs(delta) * equity * (costs.slippageBps / 10_000);
				equity -= feeCost + slipCost;
