export interface RecomputeVerdict {
	readonly valid: boolean;
	readonly mismatches: readonly string[];
}

/**
 * Independent recomputation: the verifier re-runs the engine from the same CSV + params and
 * compares field by field. Performance JSON emitted WITHOUT an engine run (spawn-resources shape,
 * Factorio) cannot survive this â€?the agent's numbers have no standing; only the engine's do.
 */
export function recomputeAndCompare(csv: string, config: EngineConfig, claimed: PerformanceReport): RecomputeVerdict {
	const fresh = runBacktest(csv, config);
	const mismatches: string[] = [];
	if (claimed.data_hash !== fresh.data_hash) mismatches.push(`data_hash: ${claimed.data_hash} â‰?${fresh.data_hash}`);
	for (const f of RECOMPUTE_FIELDS) {
		const a = claimed[f] as number;
		const b = fresh[f] as number;
		const equal = typeof a === "number" && typeof b === "number" ? Math.abs(a - b) < 1e-12 : a === b;
		if (!equal) mismatches.push(`${f}: claimed ${a} â‰?recomputed ${b}`);
	}
	return { valid: mismatches.length === 0, mismatches: Object.freeze(mismatches) };
}

/**
 * Report standing = ledger row existence (same discipline as W7's chain provenance): a report
 * whose ledger_seq does not point at a verifier-minted `quant.backtest_run` row is refused even
 * if its numbers happen to be right â€?provenance is the LEDGER, not the minted_by string.
 */
export function verifyRunProvenance(
	report: PerformanceReport,
	rows: readonly {
		seq: number;
		event_type: string;
		actor: { role: string };
		payload: Record<string, unknown> | null;
	}[],
): { valid: boolean; reason: string } {
	if (report.minted_by !== ENGINE_VERIFIER_ID) {
		return { valid: false, reason: `minted_by "${report.minted_by}" is not the engine` };
	}
	if (report.ledger_seq === null) return { valid: false, reason: "report carries no ledger_seq (never minted)" };
	const row = rows.find((r) => r.seq === report.ledger_seq);
	if (!row) return { valid: false, reason: `no ledger row at seq ${report.ledger_seq}` };
	if (row.event_type !== "quant.backtest_run" || row.actor.role !== "gatekeeper") {
		return { valid: false, reason: `seq ${report.ledger_seq} is not a verifier-minted quant.backtest_run row` };
	}
	if ((row.payload?.data_hash as string) !== report.data_hash) {
		return { valid: false, reason: "ledger row data_hash does not match the report" };
	}
	return { valid: true, reason: "verifier-minted" };
}

