/** SMA dual moving-average crossover (Q1's strategy family). */
export function smaCrossStrategy(fast: number, slow: number): Strategy {
	if (fast >= slow || fast < 1) throw new BacktestError(`sma params invalid: fast ${fast} must be < slow ${slow}`);
	return {
		name: "sma_cross",
		params: Object.freeze({ fast, slow }),
		next(view: MarketView): number {
			if (view.length < slow) return 0;
			const closes = view.closes(slow);
			const fastMa = mean(closes.slice(closes.length - fast));
			const slowMa = mean(closes);
			return fastMa > slowMa ? 1 : 0;
		},
	};
}

/** Z-score mean reversion (strong-verifier submode exemplar). */
export function meanReversionStrategy(lookback: number, entryZ: number): Strategy {
	return {
		name: "mean_reversion_z",
		params: Object.freeze({ lookback, entryZ }),
		next(view: MarketView): number {
			if (view.length < lookback) return 0;
			const closes = view.closes(lookback);
			const m = mean(closes);
			const s = std(closes);
			if (s === 0) return 0;
			const z = (view.last.close - m) / s;
			if (z < -entryZ) return 1;
			if (z > entryZ) return -1;
			return 0;
		},
	};
}

/** Time-series momentum (strong-medium submode exemplar). */
export function momentumStrategy(lookback: number): Strategy {
	return {
		name: "ts_momentum",
		params: Object.freeze({ lookback }),
		next(view: MarketView): number {
			if (view.length < lookback + 1) return 0;
			const closes = view.closes(lookback + 1);
			return closes[closes.length - 1] > closes[0] ? 1 : 0;
		},
	};
}
