const fs = require('fs');
const p = \"E:/codex-LOOP/codex-loop-s-f2/data/reports/headless-wave/adhoc-10a9f01c4d-pc7-h3-lookback/adhoc-10a9f01c4d-pc7-h3-lookback-8ae7b32193fe4a30a23299621b4c80fc/events.jsonl\";
const lines = fs.readFileSync(p, 'utf8').split(/\\r?\\n/).filter(Boolean);
const types = {};
let n = 0;
for (const line of lines) {
  let ev; try { ev = JSON.parse(line); } catch { continue; }
  const t = ev.type || '?';
  types[t] = (types[t] || 0) + 1;
  if (t === 'item.completed' || t === 'item.failed' || t === 'item.error') {
    const it = ev.item || {};
    let cmd = it.command || '';
    if (Array.isArray(cmd)) cmd = cmd.join(' ');
    cmd = String(cmd).replace(/\\s+/g, ' ').slice(0, 300);
    let out = (it.aggregated_output || '') .replace(/\\r/g, ' ').replace(/\\n/g, ' | ').slice(0, 350);
    console.log("'`[${n}] ${t} exit=${it.exit_code} status=${it.status} ${it.error || '"''}"'`);
    console.log(`  CMD: ${cmd}`);
    console.log(`  OUT: ${out}`);
    console.log('"'');
  }
  n++;
}
console.log('TYPES:', JSON.stringify(types));
